fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> Option<usize> {
    let mut left = 0;
    let mut right = arr.len();
    
    // Binary search for the first occurrence of target
    while left < right {
        let mid = left + (right - left) / 2;
        if arr[mid] < target {
            left = mid + 1;
        } else {
            // arr[mid] >= target, so potential candidate
            right = mid;
        }
    }
    
    // left is the smallest index where arr[left] >= target,
    // check if it is equal to target and within bounds
    if left < arr.len() && arr[left] == target {
        Some(left)
    } else {
        None
    }
}